def link(path, label=None):
    return f'[{label or path}](../{path})'

def write(name, title, body):
    (DOCS / name).write_text(f'# {title}\n\n[Master learning guide](AI-PPM-MASTER-LEARNING-GUIDE.md) · Snapshot: 2026-10-08, Git `ef196c9`\n\n{body.strip()}\n', encoding='utf-8')

def source(obj):
    try:
        return str(Path(inspect.getsourcefile(obj)).relative_to(ROOT)).replace('\\','/'), inspect.getsourcelines(obj)[1]
    except (TypeError, ValueError):
        return '', 0

def build_references():
    app = create_app()  # No lifespan startup: no credentials or network required.
    spec = app.openapi()
    committed = json.loads((ROOT/'packages/contracts/openapi.json').read_text(encoding='utf-8'))
    def flatten(items):
        for r in items:
            if hasattr(r, 'original_router'):
                yield from flatten(r.original_router.routes)
            elif hasattr(r,'endpoint'):
                yield r
    routes = {(r.path, m.lower()): r for r in flatten(app.routes) for m in (r.methods or [])}
    rows = ['## Complete current route inventory', '', 'Generated by importing route definitions without starting the application. Auth is a source-level description, not OpenAPI security-scheme inference. `{kind}` expands to the resource matrix below; it is not an unrestricted table name.', '', '| Method | Endpoint / handler | Purpose | Auth | Request | Response | Database family | Frontend consumer |', '|---|---|---|---|---|---|---|---|']
    def schema_name(s):
        if '$ref' in s: return s['$ref'].split('/')[-1]
        if s.get('type')=='array': return 'list['+schema_name(s['items'])+']'
        return s.get('title') or s.get('type') or ('union' if 'anyOf' in s or 'oneOf' in s else 'unspecified')
    for path, methods in spec['paths'].items():
        for method, op in methods.items():
            if method not in ['get','post','put','patch','delete','head','options']: continue
            route = routes[path,method]
            fn = inspect.unwrap(route.endpoint)
            file,line=source(fn)
            params=', '.join(p['name']+' ('+p['in']+')' for p in op.get('parameters',[]))
            body=op.get('requestBody',{}).get('content',{})
            request=', '.join(schema_name(c.get('schema',{})) for c in body.values())
            request='; '.join(x for x in [request,params] if x) or 'none'
            response='; '.join(code+': '+', '.join(schema_name(c.get('schema',{})) for c in r.get('content',{}).values()) for code,r in op['responses'].items() if code.startswith('2'))
            if '/delivery/' in path: family='ppm_* (kind); ppm_audit/ppm_requests for writes'; front='components/delivery.tsx; capacity.tsx or command-center.tsx for their kinds'; auth='Auth; RLS; write authorization'
            elif '/assessment/' in path: family='ppm_frameworks/versions, assessments, answers, events, evidence/access/requests (handler-specific)'; front='components/assessments.tsx'; auth='Auth + RLS; mutation role/assignment/grant checks'
            elif '/capacity/' in path: family='resources/calendars/availability/allocations/effort and scope'; front='components/capacity.tsx'; auth='Auth + RLS + sensitive/full-scope checks'
            elif '/command/' in path: family='delivery + capacity + command facts'; front='components/command-center.tsx'; auth='Auth + organization header/lock + RLS'
            elif '/auth/' in path or '/organization/' in path: family='identity_*; organizations; memberships'; front='app/account/identity-client.tsx'; auth='Auth' if '/organization/' in path or path.rsplit('/',1)[-1] in ['me','profile','switch','logout','sessions'] or '{session_id}' in path else 'credential/challenge or public CSRF; unsafe Origin/CSRF'
            else: family='foundation_state / dependencies'; front='app/system/page.tsx'; auth='public read'
            if '/organization/' in path: auth+='; Admin'
            database_by_handler={
                'identity.py': {
                    'csrf':'none (cookie generation)', 'login':'identity_users, memberships, organizations, identity_sessions, identity_refresh_tokens, identity_audit',
                    'refresh':'identity_refresh_tokens, identity_sessions, memberships, identity_audit on replay',
                    'me':'identity_users, identity_sessions, memberships, organizations',
                    'profile':'identity_users UPDATE; identity_audit INSERT',
                    'switch':'memberships, identity_sessions UPDATE; identity_audit INSERT; organizations',
                    'logout':'identity_sessions UPDATE; identity_audit INSERT',
                    'list_sessions':'identity_sessions SELECT', 'revoke':'identity_sessions UPDATE; identity_audit INSERT',
                    'reset_request':'identity_users SELECT; identity_challenges INSERT; private mailbox file',
                    'complete':'identity_challenges; identity_users; memberships; identity_sessions; identity_audit',
                    'member_list':'memberships JOIN identity_users', 'invite':'identity_challenges INSERT; identity_audit INSERT; mailbox file',
                    'change_member':'memberships UPDATE; identity_sessions revoke on removal; identity_audit INSERT; identity_users SELECT',
                    'audit_list':'identity_audit SELECT'},
                'assessment.py': {
                    'list_frameworks':'ppm_frameworks; ppm_framework_versions; ppm_assessment_access',
                    'create_framework':'ppm_frameworks INSERT', 'edit_framework':'ppm_frameworks UPDATE',
                    'publish_framework':'ppm_frameworks SELECT/UPDATE; ppm_framework_versions INSERT',
                    'versions':'ppm_frameworks; ppm_framework_versions SELECT',
                    'seed_examples':'ppm_frameworks INSERT for missing examples',
                    'set_access':'ppm_assessment_access; memberships; target framework/assessment',
                    'assign':'ppm_assessments INSERT; framework_versions/memberships/departments/teams validation; assessment_events INSERT',
                    'list_assessments':'ppm_assessments, framework_versions/frameworks, answers/released evidence for provisional scoring',
                    'detail':'ppm_assessments, framework_versions, answers, released evidence metadata',
                    'save_answers':'ppm_answers INSERT/UPDATE; ppm_assessments revision/results; ppm_assessment_events INSERT',
                    'submit':'ppm_assessments UPDATE; answers/framework_versions/evidence scoring; assessment_events INSERT',
                    'review':'ppm_answers adjustments; assessments state/results; assessment_events; evidence quarantine check',
                    'history':'ppm_assessments and ppm_assessment_events SELECT',
                    'evidence_list':'ppm_assessments and ppm_evidence_attachments SELECT',
                    'upload':'ppm_evidence_attachments INSERT; assessments revision/results; assessment_events; private object bytes',
                    'download':'ppm_assessments/evidence_attachments SELECT; private object bytes',
                    'delete_evidence':'ppm_evidence_attachments DELETE; assessments revision/results; assessment_events INSERT',
                    'preview_evidence':'ppm_assessments/evidence_attachments SELECT; private object bytes',
                    'release_evidence':'ppm_evidence_attachments UPDATE; assessments revision/results; assessment_events INSERT'},
                'delivery.py': {
                    'people':'memberships JOIN identity_users', 'history':'target ppm_{kind}; ppm_audit',
                    'portfolio_summary':'ppm_portfolios; ppm_projects; per-project summary sources',
                    'summary':'ppm_projects, budget_lines, expenditures, alignments, baselines, work_items, grants',
                    'listing':'ppm_{kind}; resource_skills for skill filter', 'detail':'ppm_{kind} SELECT',
                    'create':'ppm_{kind} INSERT + ppm_audit + ppm_requests; validated references and kind-specific effects',
                    'update':'ppm_{kind} UPDATE + ppm_audit; validated references and kind-specific effects'},
                'capacity.py': {'resource_summary':'ppm_resources, availability, calendars, time_off, allocations, resource_teams/skills; sensitive effort/coverage if allowed', 'saved_snapshot':'ppm_capacity_snapshots SELECT', 'team_summary':'ppm_teams/resource_teams + resource-summary sources'},
                'main.py': {'live':'none', 'ready':'foundation_state, alembic_version; Redis/storage probes', 'foundation':'foundation_state SELECT'}
            }
            family=database_by_handler.get(file.rsplit('/',1)[-1],{}).get(fn.__name__,family)
            if '/assessment/' in path and method!='get': family+='; decorator: ppm_assessment_requests + identity_audit'
            rows.append(f'| {method.upper()} | `{path}` — {link(file,fn.__name__)}:{line} | {op.get("summary",fn.__name__)} | {auth} | {request} | {response or "raw response"} | {family} | `apps/web/{front}` |')
    rows += ['', 'All Auth routes additionally read live identity session/user/membership and establish transaction-local context. The database column names direct and major helper effects; conditional reference/grant queries are explained in lifecycle chapters. Evidence download returns bytes despite its broad generated response declaration. Decorator-required assessment headers are checked in code and may be absent from generated parameter lists.', '', '## Expanded delivery resources', '', '| kind | SQL table | Input schema | API operations | Frontend |', '|---|---|---|---|---|']
    from typing import get_args
    from ppm_api.ppm_schemas import Kind, Input
    schemas=spec['components']['schemas']
    for kind in get_args(Kind):
        found=[n for n,s in schemas.items() if s.get('properties',{}).get('kind',{}).get('const')==kind and n.endswith('Input')]
        front='capacity.tsx' if kind in __import__('ppm_api.capacity',fromlist=['KINDS']).KINDS else 'command-center.tsx / delivery.tsx' if kind in ['risks','benefits','metric_plans','metric_policies','saved_views'] else 'delivery.tsx'
        rows.append(f'| `{kind}` | `ppm_{kind}` | {", ".join(found)} | GET list/detail; POST create; PATCH update subject to immutable rules | `{front}` |')
    rows += ['', '`sprint_closures` is internal: created by sprint closure, not a public delivery Kind. Immutable public kinds reject PATCH. Full payload is required by PATCH; this is not JSON Merge Patch.', '', f'Current OpenAPI contains {sum(m in ["get","post","put","patch","delete"] for p in spec["paths"].values() for m in p)} operations. Committed OpenAPI equality: **{spec == committed}**. This checks the exported contract, not runtime authorization or deployment.']
    write('18-api-contracts.md','API contracts and complete inventory',API_INTRO+'\n\n'+'\n'.join(rows))
    # Model metadata faithfully includes inherited common columns and composite constraints.
    migration_tables={}
    for p in sorted((ROOT/'services/api/migrations/versions').glob('*.py')):
        import importlib.util
        modspec=importlib.util.spec_from_file_location('learning_'+p.stem,p)
        mod=importlib.util.module_from_spec(modspec); modspec.loader.exec_module(mod)
        metadata=getattr(mod,'metadata',None)
        if metadata:
            for t in metadata.tables.values():
                if len(t.columns)>2: migration_tables.setdefault(t.name,p.name)
    migration_tables['foundation_state']='0001_foundation.py'
    model_locations={}
    for module in [identity_tables,ppm_tables,assessment_tables,command_tables]:
        for name,value in vars(module).items():
            if hasattr(value,'columns') and hasattr(value,'name'):
                model_locations[value.name]=('services/api/ppm_api/'+module.__name__.split('.')[-1]+'.py',name)
    model_locations['foundation_state']=('services/api/ppm_api/database.py','FoundationState')
    detail=['# Source-derived database dictionary','','[Database chapter](07-database.md) · [Master guide](AI-PPM-MASTER-LEARNING-GUIDE.md)','','Generated from current SQLAlchemy metadata, not a live database dump. Migration RLS/grants are documented separately. No database connection was opened. Full source files remain linked instead of reproducing large CREATE TABLE listings.','']
    for table in sorted(Base.metadata.tables.values(),key=lambda t:t.name):
        file,symbol=model_locations.get(table.name,('services/api/ppm_api/ppm_tables.py',table.name))
        kind=table.name.removeprefix('ppm_')
        assessment=table.name in [t.name for t in assessment_tables.metadata.tables.values() if t.name.removeprefix('ppm_') in assessment_tables.KINDS]
        if assessment: api='/api/v1/assessment/...'; frontend='apps/web/components/assessments.tsx'; used='assessment.py'; purpose=PURPOSES.get(kind,kind.replace('_',' '))
        elif table.name.startswith('ppm_'): api='/api/v1/delivery/'+kind if kind in get_args(Kind) else 'indirect writes / specialized reads'; frontend='apps/web/components/delivery.tsx, capacity.tsx or command-center.tsx'; used='delivery.py, capacity.py, command.py'; purpose=PURPOSES.get(kind,kind.replace('_',' '))
        else: api='/api/v1/auth/*; /api/v1/organization/*' if table.name!='foundation_state' else '/api/v1/foundation'; frontend='apps/web/app/account/identity-client.tsx' if table.name!='foundation_state' else 'apps/web/app/system/page.tsx'; used='identity.py' if table.name!='foundation_state' else 'main.py / worker app.py'; purpose=PURPOSES.get(table.name,table.name.replace('_',' '))
        constraints=[]
        for c in table.constraints:
            if c.__class__.__name__=='CheckConstraint': constraints.append(str(c.sqltext))
            elif c.__class__.__name__=='UniqueConstraint': constraints.append('UNIQUE('+', '.join(x.name for x in c.columns)+')')
        fks=['('+', '.join(e.parent.name for e in fk.elements)+') → ('+', '.join(e.target_fullname for e in fk.elements)+'); ON DELETE '+str(fk.ondelete or 'NO ACTION (default)') for fk in table.foreign_key_constraints]
        if kind in get_args(Kind):
            found=[n for n,s in schemas.items() if s.get('properties',{}).get('kind',{}).get('const')==kind and n.endswith('Input')]
            schema=', '.join(found)+' → RecordView / PageView'
            capacity_kind=kind in __import__('ppm_api.capacity',fromlist=['KINDS']).KINDS
            frontend='apps/web/components/capacity.tsx' if capacity_kind else 'apps/web/components/command-center.tsx and delivery.tsx' if kind in ['risks','benefits','metric_plans','metric_policies','saved_views'] else 'apps/web/components/delivery.tsx'
            test='tests/test_capacity.py' if capacity_kind else 'tests/test_command.py' if kind in ['risks','benefits','metric_plans','metric_policies','saved_views'] else 'tests/test_delivery.py'
            authority='delivery.authorize; tenant/project RLS; protected mutations use lock/revision checks'
